 [Test]
 public async Task ExplicitPublish_ClonesCompleteGraph_RevealsOnce_AndLeaksNoValues()
 {
  var upstream=new PublicationFakeHandler();string originalSource=CanonicalJson.Serialize(upstream.Source);await using var factory=new ApiFactory(publication:upstream);using var client=factory.CreateInternalClient();RunResponse run=await ReadyRun(client);
  Assert.That(run.Status,Is.EqualTo(RunStatus.ReadyToReveal));Assert.That(upstream.CallbackCount,Is.Zero);
  using var publish=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/publish");publish.Headers.Add("Idempotency-Key","publish-success");HttpResponseMessage response=await client.SendAsync(publish);string body=await response.Content.ReadAsStringAsync();Assert.That(response.StatusCode,Is.EqualTo(HttpStatusCode.OK),body);
  RevealSummary summary=JsonSerializer.Deserialize<RevealSummary>(body,CanonicalJson.SerializerOptions)!;int writes=upstream.WriteCount;using var replay=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/publish");replay.Headers.Add("Idempotency-Key","publish-success");string replayBody=await (await client.SendAsync(replay)).Content.ReadAsStringAsync();
  RunResponse final=(await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{run.RunId}",CanonicalJson.SerializerOptions))!;string reveal=await client.GetStringAsync($"/drillingoperations/api/runs/{run.RunId}/reveal");string audit=await client.GetStringAsync($"/drillingoperations/api/audit?scenarioId={TestData.ScenarioId}");var store=factory.Services.GetRequiredService<DrillingOperationsStore>();var sideEffects=await store.GetSideEffectCountsAsync(run.RunId);
  Assert.Multiple(()=>{Assert.That(final.Status,Is.EqualTo(RunStatus.Revealed));Assert.That(final.CurrentStage,Is.EqualTo(RunStageKind.S8PublishReveal));Assert.That(upstream.CallbackCount,Is.EqualTo(1));Assert.That(upstream.PrepareCount,Is.EqualTo(1));Assert.That(upstream.FinalizeCount,Is.EqualTo(1));Assert.That(upstream.CallbackKey,Is.EqualTo("analysis-callback-test-key"));Assert.That(upstream.WriteCount,Is.EqualTo(writes));Assert.That(replayBody,Is.EqualTo(body));Assert.That(summary.VerifiedOperationCount,Is.EqualTo(summary.OperationCount));Assert.That(summary.OperationCount,Is.EqualTo(223));Assert.That(CanonicalJson.Serialize(upstream.Source),Is.EqualTo(originalSource));Assert.That(summary.ProductionMonthCount,Is.EqualTo(60));Assert.That(summary.ObservationModelVersion,Is.EqualTo("observation-model-v1"));Assert.That(summary.ValidTimeUtc,Is.EqualTo(DateTimeOffset.Parse("2025-01-02T00:00:00Z")));Assert.That(sideEffects,Is.EqualTo((1,1)));Assert.That(reveal+audit,Does.Not.Contain("reportedOilM3").And.Not.Contain("correctedOilM3").And.Not.Contain("surveyStationList").And.Not.Contain("pressurePa").And.Not.Contain("completionBindingId").And.Not.Contain("worldId"));});
  Assert.That(string.Join("",upstream.PublishedPayloads),Does.Not.Contain("ProductionTruth").And.Not.Contain("TruthSampleBatch").And.Not.Contain("bottomHolePressurePa").And.Not.Contain("completionBindingId").And.Not.Contain("worldId"));JsonElement callback=upstream.CallbackBody!.Value;string[] verifiedHashes=upstream.PublishedPayloads.Select(x=>{using var document=JsonDocument.Parse(x);return PublicationJson.BusinessContentHash(document.RootElement);}).Order().ToArray();string[] evidenceHashes=callback.GetProperty("evidence").EnumerateArray().Select(x=>x.GetProperty("contentSha256").GetString()!).Order().ToArray();JsonElement productionWell=upstream.PublishedPayloads.Select(x=>JsonDocument.Parse(x).RootElement.Clone()).Single(x=>PublicationJson.TryProperty(x,"dataset",out var dataset)&&PublicationJson.TryProperty(dataset,"monthlyProduction",out var months)&&months.GetArrayLength()==60);string publicProductionHash=PublicationJson.MonthlyProductionHash(productionWell);JsonElement clonePackage=callback.GetProperty("clonePackage");string cloneJson=clonePackage.GetRawText();Assert.Multiple(()=>{Assert.That(callback.GetProperty("observationModelVersion").GetString(),Is.EqualTo("observation-model-v1"));Assert.That(string.Join("",upstream.PublishedPayloads),Does.Contain("synthetic-petrophysics-v2"));Assert.That(callback.GetProperty("evidence").GetArrayLength(),Is.EqualTo(summary.EvidenceCount));Assert.That(evidenceHashes,Is.EqualTo(verifiedHashes));Assert.That(clonePackage.GetProperty("fieldId").GetGuid(),Is.EqualTo(Guid.Parse(summary.ClonedFieldId)));Assert.That(clonePackage.GetProperty("generatedAt").GetDateTimeOffset(),Is.EqualTo(summary.ValidTimeUtc));Assert.That(clonePackage.GetProperty("sourceCounts").EnumerateObject().Sum(x=>x.Value.GetInt32()),Is.EqualTo(summary.EvidenceCount));Assert.That(cloneJson,Does.Not.Contain("ProductionTruth").And.Not.Contain("TruthSampleBatch").And.Not.Contain("completionBindingId").And.Not.Contain("worldId"));Assert.That(callback.GetProperty("productionSeries").GetProperty("contentSha256").GetString(),Is.EqualTo(publicProductionHash));Assert.That(summary.ProductionContentSha256,Is.EqualTo(publicProductionHash));Assert.That(callback.GetProperty("productionSeries").GetProperty("monthCount").GetInt32(),Is.EqualTo(60));Assert.That(callback.GetProperty("productionSeries").GetProperty("checkpointYears").EnumerateArray().Select(x=>x.GetInt32()),Is.EqualTo(new[]{1,3,5}));Assert.That(upstream.ActivationCount,Is.EqualTo(223));Assert.That(upstream.TrajectoryReadWithoutStationsCount,Is.Zero);Assert.That(upstream.PublishedPayloads.Where(x=>x.Contains("SurveyStationList",StringComparison.OrdinalIgnoreCase)).All(x=>!x.Contains("\"SurveyStationList\":null",StringComparison.OrdinalIgnoreCase)),Is.True);});
 }
