 [Test]
 public async Task LegacyNormalizationFailure_MigratesOnce_PreservesVerifiedOperations_AndResumesPublication()
 {
  var upstream=new PublicationFakeHandler{ScenarioWellMismatch=true};await using var factory=new ApiFactory(publication:upstream);using var client=factory.CreateInternalClient();RunResponse run=await ReadyRun(client);Assert.That((await Publish(client,run.RunId,"legacy-normalization-first")).StatusCode,Is.EqualTo(HttpStatusCode.Conflict));
  Dictionary<string,(string Hash,string Json)> verifiedBefore;int incompleteBefore;await using(var connection=new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={factory.DatabasePath}")){await connection.OpenAsync();verifiedBefore=await ReadVerifiedAsync(connection,run.RunId);incompleteBefore=await CountIncompleteAsync(connection,run.RunId);Assert.Multiple(()=>{Assert.That(verifiedBefore.Count,Is.GreaterThan(1));Assert.That(incompleteBefore,Is.GreaterThan(0));});await using var legacy=connection.CreateCommand();legacy.CommandText="""
   UPDATE Runs SET Status='Failed',CurrentStage=$s8,EndedUtc=$ended,DiagnosticCode='PublicationEntityIdentityConflict' WHERE RunId=$run;
   UPDATE RunStages SET Status='Failed',EndedUtc=$ended,Diagnostics='PublicationEntityIdentityConflict' WHERE RunId=$run AND Stage=$s8;
   """;legacy.Parameters.AddWithValue("$s8",(int)RunStageKind.S8PublishReveal);legacy.Parameters.AddWithValue("$ended","2026-09-04T00:00:00.0000000+00:00");legacy.Parameters.AddWithValue("$run",run.RunId);await legacy.ExecuteNonQueryAsync();}
  var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();RunResponse recovered=(await restarted.GetRunAsync(run.RunId))!;StageResponse s8=(await restarted.GetStagesAsync(run.RunId)).Single(x=>x.Stage==RunStageKind.S8PublishReveal);Dictionary<string,(string Hash,string Json)> verifiedAfter;string runDiagnostic;int incompleteAfter;await using(var connection=new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={factory.DatabasePath}")){await connection.OpenAsync();verifiedAfter=await ReadVerifiedAsync(connection,run.RunId);incompleteAfter=await CountIncompleteAsync(connection,run.RunId);await using var diagnostic=connection.CreateCommand();diagnostic.CommandText="SELECT DiagnosticCode FROM Runs WHERE RunId=$run";diagnostic.Parameters.AddWithValue("$run",run.RunId);runDiagnostic=(string)(await diagnostic.ExecuteScalarAsync())!;}
  Assert.Multiple(()=>{Assert.That(recovered.Status,Is.EqualTo(RunStatus.PublishFailed));Assert.That(recovered.CurrentStage,Is.EqualTo(RunStageKind.S8PublishReveal));Assert.That(recovered.EndedUtc,Is.Null);Assert.That(runDiagnostic,Is.EqualTo("PublicationReadAfterWriteMismatch"));Assert.That(s8.Status,Is.EqualTo(StageStatus.AwaitingDependency));Assert.That(s8.DiagnosticCode,Is.EqualTo("PublicationReadAfterWriteMismatch"));Assert.That(s8.EndedUtc,Is.Null);Assert.That(verifiedAfter,Is.EqualTo(verifiedBefore));Assert.That(incompleteAfter,Is.EqualTo(incompleteBefore));Assert.That((restarted.GetAuditAsync(run.ScenarioId).Result).Count(x=>x.Action=="publication.normalization-recovery"),Is.EqualTo(1));});Assert.That(await restarted.VerifyAuditChainAsync(run.ScenarioId),Is.True);await restarted.InitializeAsync();Assert.That((await restarted.GetAuditAsync(run.ScenarioId)).Count(x=>x.Action=="publication.normalization-recovery"),Is.EqualTo(1));
  upstream.ScenarioWellMismatch=false;upstream.NormalizeStoredScenarioWell();Assert.That((await Publish(client,run.RunId,"legacy-normalization-retry")).StatusCode,Is.EqualTo(HttpStatusCode.OK));Assert.Multiple(()=>{Assert.That(upstream.PrepareCount,Is.EqualTo(1));Assert.That(upstream.FinalizeCount,Is.EqualTo(1));});
  static async Task<Dictionary<string,(string Hash,string Json)>> ReadVerifiedAsync(Microsoft.Data.Sqlite.SqliteConnection connection,string runId){await using var command=connection.CreateCommand();command.CommandText="SELECT o.OperationId,s.ResultHash,s.ResultBusinessJson FROM PublicationOperations o JOIN PublicationOperationStates s ON s.OperationId=o.OperationId JOIN PublicationPlans p ON p.PublicationPlanId=o.PublicationPlanId WHERE p.RunId=$run AND s.Status='Verified' ORDER BY o.Sequence";command.Parameters.AddWithValue("$run",runId);var result=new Dictionary<string,(string,string)>();await using var reader=await command.ExecuteReaderAsync();while(await reader.ReadAsync())result.Add(reader.GetString(0),(reader.GetString(1),reader.GetString(2)));return result;}
  static async Task<int> CountIncompleteAsync(Microsoft.Data.Sqlite.SqliteConnection connection,string runId){await using var command=connection.CreateCommand();command.CommandText="SELECT COUNT(*) FROM PublicationOperations o JOIN PublicationOperationStates s ON s.OperationId=o.OperationId JOIN PublicationPlans p ON p.PublicationPlanId=o.PublicationPlanId WHERE p.RunId=$run AND s.Status<>'Verified'";command.Parameters.AddWithValue("$run",runId);return Convert.ToInt32(await command.ExecuteScalarAsync());}
 }
