 public async Task LegacyPublicationAdapterState_MigratesAndExplicitPublishIsAccepted()
 {
  var upstream=new PublicationFakeHandler();await using var factory=new ApiFactory(publication:upstream);using var client=factory.CreateInternalClient();RunResponse run=await ReadyRun(client);Assert.That(run.Status,Is.EqualTo(RunStatus.ReadyToReveal),"Fresh S7 completion must be explicitly ready to reveal.");await using(var connection=new Microsoft.Data.Sqlite.SqliteConnection($"Data Source={factory.DatabasePath}")){await connection.OpenAsync();await using var legacy=connection.CreateCommand();legacy.CommandText="UPDATE Runs SET Status='AwaitingDependency',CurrentStage=$s8 WHERE RunId=$run;UPDATE RunStages SET Status='AwaitingDependency',StartedUtc=$time,EndedUtc=$time,Diagnostics='PublicationAdapterUnavailable' WHERE RunId=$run AND Stage=$s8;";legacy.Parameters.AddWithValue("$s8",(int)RunStageKind.S8PublishReveal);legacy.Parameters.AddWithValue("$time","2025-01-01T00:00:00.0000000+00:00");legacy.Parameters.AddWithValue("$run",run.RunId);await legacy.ExecuteNonQueryAsync();}var restarted=new DrillingOperationsStore($"Data Source={factory.DatabasePath}",TimeProvider.System);await restarted.InitializeAsync();Assert.That((await restarted.GetRunAsync(run.RunId))!.Status,Is.EqualTo(RunStatus.ReadyToReveal));Assert.That((await Publish(client,run.RunId,"legacy-ready-publish")).StatusCode,Is.EqualTo(HttpStatusCode.OK));Assert.Multiple(()=>{Assert.That(upstream.PrepareCount,Is.EqualTo(1));Assert.That(upstream.FinalizeCount,Is.EqualTo(1));});
 }
