e":-1,"BoreholeRadius":0,"DerivedAnything":1}]}""");using var missingAuthoritative=JsonDocument.Parse("""{"SurveyStationList":[{"MD":10,"Abscissa":10,"X":1.25,"Y":-2.5,"TVD":9.75,"Inclination":0.1,"Z":9.75,"RiemannianNorth":1.25,"RiemannianEast":-2.5,"Latitude":1,"Longitude":-1,"BoreholeRadius":0}]}""");Assert.Multiple(()=>{Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,enriched.RootElement),Is.True);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,wrongCoordinates.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,wrongY.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,wrongTvd.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,wrongZ.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expectedOutside.RootElement,outside.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,arbitrary.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,missingAuthoritative.RootElement),Is.False);});
