 {
  var expectedMonths=Enumerable.Range(0,60).Select(i=>new Dictionary<string,object?>{{"Month",i+1},{"Volume",i+0.5}}).ToArray();var actualMonths=Enumerable.Range(0,60).Select(i=>new Dictionary<string,object?>{{"Month",i+1},{"Volume",i+0.5},{"SourceArtifactID",null}}).ToArray();using var expected=JsonDocument.Parse(JsonSerializer.Serialize(new{Lifecycle=new[]{new{EffectiveAt="2024-01-02T00:00:00+00:00",FirstSeenAt="2024-01-02T00:00:00+00:00"}},MonthlyProduction=expectedMonths}));using var actual=JsonDocument.Parse(JsonSerializer.Serialize(new{Lifecycle=new[]{new{EffectiveAt="2024-01-01T19:00:00-05:00",FirstSeenAt="2024-01-01T19:00:00-05:00",SourceArtifactID=(string?)null}},MonthlyProduction=actualMonths}));using var reverseExpected=JsonDocument.Parse("""{"SourceArtifactID":null}""");using var reverseActual=JsonDocument.Parse("{}");using var different=JsonDocument.Parse("""{"Lifecycle":[{"EffectiveAt":"2024-01-01T19:00:01-05:00","FirstSeenAt":"2024-01-01T19:00:00-05:00","SourceArtifactID":null}],"MonthlyProduction":[]}""");using var extra=JsonDocument.Parse("""{"value":1,"SourceArtifactID":"non-null"}""");using var baseValue=JsonDocument.Parse("""{"value":1}""");using var labelA=JsonDocument.Parse("""{"Label":"2024-01-02T00:00:00+00:00"}""");using var labelB=JsonDocument.Parse("""{"Label":"2024-01-01T19:00:00-05:00"}""");Assert.Multiple(()=>{Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,actual.RootElement),Is.True);Assert.That(PublicationJson.BusinessContentMatches(reverseExpected.RootElement,reverseActual.RootElement),Is.True);Assert.That(PublicationJson.BusinessContentMatches(expected.RootElement,different.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(baseValue.RootElement,extra.RootElement),Is.False);Assert.That(PublicationJson.BusinessContentMatches(labelA.RootElement,labelB.RootElement),Is.False);});
