 static async Task<HttpResponseMessage> Publish(HttpClient client,string runId,string key){using var request=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{runId}/publish");request.Headers.Add("Idempotency-Key",key);return await client.SendAsync(request);}
 internal static async Task<RunResponse> ReadyRun(HttpClient client){using var bind=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/scenarios/{TestData.ScenarioId}/bind"){Content=JsonContent.Create(TestData.Binding())};bind.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());(await client.SendAsync(bind)).EnsureSuccessStatusCode();using var create=new HttpRequestMessage(HttpMethod.Post,"/drillingoperations/api/runs"){Content=JsonContent.Create(TestData.Run())};create.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());var created=await client.SendAsync(create);var run=JsonSerializer.Deserialize<RunResponse>(await created.Content.ReadAsStringAsync(),CanonicalJson.SerializerOptions)!;await Wait(client,run.RunId,x=>x.Status==RunStatus.AwaitingApproval);using var approve=new HttpRequestMessage(HttpMethod.Post,$"/drillingoperations/api/runs/{run.RunId}/completion/approve");approve.Headers.Add("Idempotency-Key",Guid.NewGuid().ToString());approve.Headers.Add("X-DrillSim-Human-Actor","publisher");(await client.SendAsync(approve)).EnsureSuccessStatusCode();return await Wait(client,run.RunId,x=>x.Status==RunStatus.ReadyToReveal);}
 static async Task<RunResponse> Wait(HttpClient client,string runId,Func<RunResponse,bool> predicate){for(int i=0;i<500;i++){var run=(await client.GetFromJsonAsync<RunResponse>($"/drillingoperations/api/runs/{runId}",CanonicalJson.SerializerOptions))!;if(predicate(run))return run;await Task.Delay(20);}throw new AssertionException("Run timeout.");}
}
